// src/analysis/__tests__/sdk-detection.test.ts
// `apix status` must recognise the Hedera SDK under both names: apps generated
// by 2.2.0+ use @hiero-ledger/sdk, apps generated by 2.1.x use @hashgraph/sdk.
import fs from 'fs-extra';
import os from 'os';
import path from 'path';
import { ProjectAnalyzer } from '../project-analyzer';
import { declaredHederaSdk } from '../../utils/hedera-sdk';

jest.mock('../../utils/logger');

describe('Hedera SDK detection', () => {
  let root: string;

  beforeEach(async () => {
    root = await fs.mkdtemp(path.join(os.tmpdir(), 'apix-sdk-detect-'));
  });

  afterEach(async () => {
    await fs.remove(root);
  });

  async function accountStatus(dependencies: Record<string, string>) {
    // A supported framework, or analyzeProject refuses the project
    await fs.writeJSON(path.join(root, 'package.json'), {
      name: 'app', version: '1.0.0', dependencies: { next: '16.4.0', react: '19.2.8', ...dependencies }
    });
    const analyzer = new ProjectAnalyzer();
    const context = await analyzer.analyzeProject(root);
    return (await analyzer.getIntegrationStatus(context)).account;
  }

  it('apix status reports the SDK for @hiero-ledger/sdk', async () => {
    const account = await accountStatus({ '@hiero-ledger/sdk': '~2.90.0' });
    expect(account.integrated).toBe(true);
    expect(account.version).toBe('~2.90.0');
  });

  it('apix status reports the SDK for @hashgraph/sdk (apps generated by 2.1.x)', async () => {
    const account = await accountStatus({ '@hashgraph/sdk': '~2.80.0' });
    expect(account.integrated).toBe(true);
    expect(account.version).toBe('~2.80.0');
  });

  it('apix status reports no SDK when neither is declared', async () => {
    const account = await accountStatus({});
    expect(account.integrated).toBe(false);
  });

  it('prefers @hiero-ledger/sdk when both are declared', () => {
    expect(declaredHederaSdk({
      dependencies: { '@hashgraph/sdk': '~2.80.0' },
      devDependencies: { '@hiero-ledger/sdk': '~2.90.0' },
    })).toEqual({ name: '@hiero-ledger/sdk', range: '~2.90.0' });
    expect(declaredHederaSdk({ dependencies: { '@hashgraph/sdk': '~2.80.0' } }))
      .toEqual({ name: '@hashgraph/sdk', range: '~2.80.0' });
    expect(declaredHederaSdk({})).toBeUndefined();
  });
});
